@@ -0,0 +1,25 @@
+// Qt never reads the compositor's NumLock state at startup (QTBUG-32687), so
+// keypad digits reach the password field as cursor keys carrying no text.
+// Values are Qt::Key_* from qnamespace.h; QML enums are not visible here.
+function keypadDigit(key) {
+  switch (key) {
+    case 0x01000006: return "0" // Key_Insert
+    case 0x01000011: return "1" // Key_End
+    case 0x01000015: return "2" // Key_Down
+    case 0x01000017: return "3" // Key_PageDown
+    case 0x01000012: return "4" // Key_Left
+    case 0x0100000b: return "5" // Key_Clear
+    case 0x01000014: return "6" // Key_Right
+    case 0x01000010: return "7" // Key_Home
+    case 0x01000013: return "8" // Key_Up
+    case 0x01000016: return "9" // Key_PageUp
+    case 0x01000007: return "." // Key_Delete
+  }
+  return ""
+}
+
+if (typeof module !== "undefined") {
+  module.exports = {
+    keypadDigit: keypadDigit
+  }
+}

@@ -2,6 +2,7 @@ import QtQuick
 import QtQuick.Effects
 import qs.Commons
 import qs.Ui
+import "LockModel.js" as LockModel

 Item {
   id: root
@@ -52,6 +53,17 @@ Item {
     passwordInput.forceActiveFocus()
   }

+  // With NumLock desynced the keypad sends Home, Up, PageUp and so on with
+  // KeypadModifier set and no text, which the field would otherwise treat as
+  // cursor movement. The top row never carries the modifier, so it is untouched.
+  function insertKeypadDigit(event) {
+    if (passwordInput.readOnly || !(event.modifiers & Qt.KeypadModifier)) return false
+    var digit = LockModel.keypadDigit(event.key)
+    if (digit === "") return false
+    passwordInput.insert(passwordInput.cursorPosition, digit)
+    return true
+  }
+
   function clearPassword() {
     passwordTextEdited("")
   }
@@ -181,6 +193,8 @@ Item {
           if (event.key === Qt.Key_Escape || (event.modifiers & Qt.ControlModifier && event.key === Qt.Key_U)) {
             root.passwordTextEdited("")
             event.accepted = true
+          } else if (root.insertKeypadDigit(event)) {
+            event.accepted = true
           }
         }
       }
